              const maxScale = (wp.beaconScale || 10) * 100; // Convert to percentage (10 = 1000%)
              const ringDuration = RIPPLE_BASE_DURATION * (maxScale / RIPPLE_REFERENCE_SCALE);
              const spawnInterval = ringDuration;
              
