          smoothedZoom += (targetZoom - smoothedZoom) * ZOOM_SMOOTHING;
          smoothedCenterX += (targetCenterX - smoothedCenterX) * CAMERA_SMOOTHING;
          smoothedCenterY += (targetCenterY - smoothedCenterY) * CAMERA_SMOOTHING;
